package lt.tomexas.serverselector.selector.ui;

import net.kyori.adventure.key.Key;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;

/**
 * Characters assigned to the selector's glyphs in nexo/glyphs/selector.yml (generated by
 * tools/build_selector_assets.py). Without Nexo the pack is missing, so plain-text fallbacks are used.
 */
public enum Glyph {
    CURSOR_ARROW("selector_cursor_arrow", '\uE300', "\u2196"),
    CURSOR_HAND("selector_cursor_hand", '\uE301', "\u261B"),
    ARROW_LEFT("selector_arrow_left", '\uE302', "\u25C0"),
    ARROW_RIGHT("selector_arrow_right", '\uE303', "\u25B6"),
    CARD("selector_card", '\uE304', ""),
    CARD_SELECTED("selector_card_selected", '\uE305', ""),
    PANEL("selector_panel", '\uE306', ""),
    DIM("selector_dim", '\uE307', ""),
    VIGNETTE("selector_vignette", '\uE308', ""),
    BUTTON("selector_button", '\uE309', ""),
    BUTTON_HOVER("selector_button_hover", '\uE30A', ""),
    BAR_TRACK("selector_bar_track", '\uE30B', ""),
    BAR_FILL("selector_bar_fill", '\uE30C', ""),
    PLAY("selector_play", '\uE30D', ""),
    PLAY_HOVER("selector_play_hover", '\uE30E', ""),
    PLAY_DISABLED("selector_play_disabled", '\uE30F', ""),
    ICON_SWORD("selector_icon_sword", '\uE310', "\u2694"),
    ICON_PICKAXE("selector_icon_pickaxe", '\uE311', "\u26CF"),
    ICON_AXE("selector_icon_axe", '\uE312', "\u25C6"),
    ICON_BOW("selector_icon_bow", '\uE313', "\u27B6"),
    ICON_HAMMER("selector_icon_hammer", '\uE314', "\u2692"),
    ICON_WAND("selector_icon_wand", '\uE315', "\u2727"),
    ICON_BOMB("selector_icon_bomb", '\uE316', "\u2738"),
    ICON_TORCH("selector_icon_torch", '\uE317', "\u2600"),
    ICON_STAR("selector_icon_star", '\uE318', "\u2605");

    // Nexo puts glyphs in its own font (its Glyphs.default_font setting), not minecraft:default
    private static final Key FONT = Key.key("nexo", "default");

    private static boolean nexoAvailable;

    private final String id;
    private final char character;
    private final String fallback;

    Glyph(String id, char character, String fallback) {
        this.id = id;
        this.character = character;
        this.fallback = fallback;
    }

    public String id() {
        return id;
    }

    public char character() {
        return character;
    }

    /** The glyph as white text, so the texture is drawn untinted. */
    public Component component() {
        if (nexoAvailable) {
            return Component.text(String.valueOf(character), NamedTextColor.WHITE).font(FONT);
        }
        return Component.text(fallback, NamedTextColor.WHITE);
    }

    public static void setNexoAvailable(boolean available) {
        nexoAvailable = available;
    }

    public static Glyph fromId(String id) {
        for (Glyph glyph : values()) {
            if (glyph.id.equalsIgnoreCase(id)) return glyph;
        }
        return null;
    }
}
